        let (s, g) = (triple(size)?, triple(per_group)?);
        let (s, g) = (Size::new(s[0], s[1], s[2]), Size::new(g[0], g[1], g[2]));
        let c = compute(encoder)?;
        if threads { c.dispatch_threads(s, g) } else { c.dispatch_threadgroups(s, g) }.map_err(e("dispatch"))?;
        Ok(true)
    })
}

